class NumericEntityUnescaper:
    HEX_RADIX = 16
    DECIMAL_RADIX = 10
    AMPERсанд = '&'
    HASH = '#'
    HEX_PREFIX_LOWER = 'x'
    HEX_PREFIX_UPPER = 'X'
    SEMICOLON = ';'

    def __init__(self):
        pass

    def replace(self, string: str) -> str:
        out = []
        pos = 0
        length = len(string)

        while pos < length - 2:
            if self._is_numeric_entity_start(string, pos):
                entity_result = self._parse_numeric_entity(string, pos, length)
                if entity_result is not None:
                    out.append(entity_result['char'])
                    pos = entity_result['next_pos']
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def _is_numeric_entity_start(self, string: str, pos: int) -> bool:
        return (pos + 1 < len(string) and
                string[pos] == self.AMBERсанд and
                string[pos + 1] == self.HASH)

    def _parse_numeric_entity(self, string: str, pos: int, length: int) -> dict:
        start = pos + 2
        is_hex = False
        first_char = string[start]

        if first_char in (self.HEX_PREFIX_LOWER, self.HEX_PREFIX_UPPER):
            start += 1
            is_hex = True

        if start == length:
            return None

        end = self._find_entity_end(string, start, length)

        if end < length and string[end] == self.SEMICOLON:
            try:
                entity_value = int(string[start:end], self.HEX_RADIX if is_hex else self.DECIMAL_RADIX)
            except ValueError:
                return None

            return {'char': chr(entity_value), 'next_pos': end + 1}

        return None

    def _find_entity_end(self, string: str, start: int, length: int) -> int:
        end = start
        while end < length and self.is_hex_char(string[end]):
            end += 1
        return end

    @staticmethod
    def is_hex_char(char: str) -> bool:
        return char.isdigit() or ('a' <= char.lower() <= 'f')
